import React, { useEffect, useMemo, useState } from 'react';
import { SearchableSelect } from './SearchableSelect';
import { formatAddressLine } from '../../../utils/brazilianInput';
import { maskCnpjInput } from '../../../api/billing';

const PERIOD_OPTIONS = [
  { value: 'mensal', label: 'Mensal' },
  { value: 'trimestral', label: 'Trimestral' },
  { value: 'anual', label: 'Anual' },
];

function todayIso() {
  return new Date().toISOString().slice(0, 10);
}

export const emptyContractForm = {
  clientId: '',
  sendEmail: '',
  contractDate: todayIso(),
  startDate: todayIso(),
  durationMonths: '12',
  paymentDay: '10',
  subscriptionPeriod: 'mensal',
  implementationFee: '',
  subscriptionFee: '',
  scope: '',
  clientLegalName: '',
  clientCnpj: '',
  clientAddress: '',
  city: 'Belo Horizonte - MG',
  bodyText: '',
};

function applyTemplate(template, values) {
  return String(template || '').replace(/\{\{\s*([a-zA-Z0-9_]+)\s*\}\}/g, (_, key) => {
    if (key === 'implementationFeeFormatted') return values.implementationFee || '';
    if (key === 'subscriptionFeeFormatted') return values.subscriptionFee || '';
    if (key === 'contractDateFormatted') {
      const [y, m, d] = String(values.contractDate || '').split('-');
      return d && m && y ? `${d}/${m}/${y}` : values.contractDate || '';
    }
    if (key === 'startDateFormatted') {
      const [y, m, d] = String(values.startDate || '').split('-');
      return d && m && y ? `${d}/${m}/${y}` : values.startDate || '';
    }
    if (key === 'implementationFeeExtenso' || key === 'subscriptionFeeExtenso' || key === 'durationMonthsExtenso') {
      return `{{${key}}}`;
    }
    return values[key] != null ? String(values[key]) : '';
  });
}

export function ContractForm({
  form,
  setForm,
  clientOptions,
  clientsById,
  templateBody,
  submitting,
  previewing,
  onCancel,
  onPreview,
  onSubmit,
}) {
  const [bodyTouched, setBodyTouched] = useState(false);

  const selectedClient = useMemo(
    () => clientsById?.[form.clientId] || clientOptions.find((c) => c.value === form.clientId) || null,
    [clientOptions, clientsById, form.clientId]
  );

  useEffect(() => {
    if (!templateBody || bodyTouched) return;
    setForm((prev) => ({
      ...prev,
      bodyText: applyTemplate(templateBody, prev),
    }));
  }, [templateBody, bodyTouched, setForm]);

  const selectClient = (clientId) => {
    const option = clientOptions.find((c) => c.value === clientId);
    const full = clientsById?.[clientId];
    const address = full ? formatAddressLine(full) : '';
    setForm((prev) => {
      const next = {
        ...prev,
        clientId: clientId || '',
        sendEmail: full?.billingEmail || prev.sendEmail,
        clientLegalName: full?.legalName || option?.label || '',
        clientCnpj: full?.cnpjFormatted ? maskCnpjInput(full.cnpjFormatted) : option?.hint?.includes('*') ? '' : maskCnpjInput(option?.hint || ''),
        clientAddress: address || prev.clientAddress,
      };
      if (!bodyTouched && templateBody) {
        next.bodyText = applyTemplate(templateBody, next);
      }
      return next;
    });
  };

  const updateField = (field, value) => {
    setForm((prev) => {
      const next = { ...prev, [field]: value };
      if (!bodyTouched && templateBody && field !== 'bodyText' && field !== 'sendEmail') {
        next.bodyText = applyTemplate(templateBody, next);
      }
      return next;
    });
  };

  return (
    <form className="admin-form" onSubmit={onSubmit}>
      <section className="nfse-card">
        <header className="nfse-card__header">
          <h3>Cliente e envio</h3>
          <p>Vincule a um cliente cadastrado. O e-mail de envio pode ser diferente do cadastrado.</p>
        </header>
        <div className="nfse-card__body">
          <div className="admin-form-grid">
            <div className="admin-field">
              <label htmlFor="contract-client">Cliente</label>
              <SearchableSelect
                id="contract-client"
                value={form.clientId}
                onChange={selectClient}
                options={clientOptions}
                placeholder="Buscar cliente..."
                required
              />
            </div>
            <div className="admin-field">
              <label htmlFor="contract-email">E-mail de envio</label>
              <input
                id="contract-email"
                type="email"
                value={form.sendEmail}
                onChange={(e) => updateField('sendEmail', e.target.value)}
                placeholder="destinatario@empresa.com"
                required
              />
            </div>
          </div>
          {selectedClient && (
            <p className="area-lead" style={{ marginTop: 12, marginBottom: 0 }}>
              Selecionado: <strong>{form.clientLegalName || selectedClient.label}</strong>
            </p>
          )}
        </div>
      </section>

      <section className="nfse-card">
        <header className="nfse-card__header">
          <h3>Variáveis do contrato</h3>
          <p>Taxa de implementação, assinatura e demais condições</p>
        </header>
        <div className="nfse-card__body">
          <div className="admin-form-grid admin-form-grid--3">
            <div className="admin-field">
              <label>Data do contrato</label>
              <input type="date" value={form.contractDate} onChange={(e) => updateField('contractDate', e.target.value)} required />
            </div>
            <div className="admin-field">
              <label>Início da vigência</label>
              <input type="date" value={form.startDate} onChange={(e) => updateField('startDate', e.target.value)} required />
            </div>
            <div className="admin-field">
              <label>Prazo (meses)</label>
              <input type="number" min="1" value={form.durationMonths} onChange={(e) => updateField('durationMonths', e.target.value)} required />
            </div>
            <div className="admin-field">
              <label>Taxa de implementação (R$)</label>
              <input value={form.implementationFee} onChange={(e) => updateField('implementationFee', e.target.value)} placeholder="5.000,00" required />
            </div>
            <div className="admin-field">
              <label>Valor da assinatura (R$)</label>
              <input value={form.subscriptionFee} onChange={(e) => updateField('subscriptionFee', e.target.value)} placeholder="1.500,00" required />
            </div>
            <div className="admin-field">
              <label>Periodicidade</label>
              <select value={form.subscriptionPeriod} onChange={(e) => updateField('subscriptionPeriod', e.target.value)} required>
                {PERIOD_OPTIONS.map((opt) => (
                  <option key={opt.value} value={opt.value}>{opt.label}</option>
                ))}
              </select>
            </div>
            <div className="admin-field">
              <label>Dia de vencimento</label>
              <input type="number" min="1" max="28" value={form.paymentDay} onChange={(e) => updateField('paymentDay', e.target.value)} />
            </div>
            <div className="admin-field">
              <label>Cidade de foro</label>
              <input value={form.city} onChange={(e) => updateField('city', e.target.value)} />
            </div>
            <div className="admin-field">
              <label>CNPJ do contratante</label>
              <input value={form.clientCnpj} onChange={(e) => updateField('clientCnpj', maskCnpjInput(e.target.value))} />
            </div>
            <div className="admin-field" style={{ gridColumn: '1 / -1' }}>
              <label>Razão social do contratante</label>
              <input value={form.clientLegalName} onChange={(e) => updateField('clientLegalName', e.target.value)} required />
            </div>
            <div className="admin-field" style={{ gridColumn: '1 / -1' }}>
              <label>Endereço do contratante</label>
              <input value={form.clientAddress} onChange={(e) => updateField('clientAddress', e.target.value)} />
            </div>
            <div className="admin-field" style={{ gridColumn: '1 / -1' }}>
              <label>Objeto / escopo do serviço</label>
              <textarea rows={3} value={form.scope} onChange={(e) => updateField('scope', e.target.value)} required />
            </div>
          </div>
        </div>
      </section>

      <section className="nfse-card">
        <header className="nfse-card__header">
          <h3>Texto do contrato</h3>
          <p>Modelo preenchido automaticamente. Edite livremente antes de gerar o PDF.</p>
        </header>
        <div className="nfse-card__body">
          <div className="admin-field">
            <textarea
              rows={22}
              value={form.bodyText}
              onChange={(e) => {
                setBodyTouched(true);
                updateField('bodyText', e.target.value);
              }}
              required
            />
          </div>
          <button
            type="button"
            className="admin-btn admin-btn--secondary admin-btn--sm"
            onClick={() => {
              setBodyTouched(false);
              if (templateBody) {
                setForm((prev) => ({ ...prev, bodyText: applyTemplate(templateBody, prev) }));
              }
            }}
          >
            Restaurar modelo
          </button>
        </div>
      </section>

      <div className="admin-form-actions">
        <button type="button" className="admin-btn admin-btn--secondary" onClick={onCancel} disabled={submitting}>
          Cancelar
        </button>
        <button type="button" className="admin-btn admin-btn--secondary" onClick={onPreview} disabled={submitting || previewing}>
          {previewing ? 'Gerando prévia...' : 'Ver prévia'}
        </button>
        <button type="submit" className="admin-btn" disabled={submitting || !form.clientId}>
          {submitting ? 'Enviando...' : 'Gerar PDF e enviar'}
        </button>
      </div>
    </form>
  );
}
